#include "aad.hpp"
#include <stdexcept>
#include <vector>
#include <stack>
#include <memory>
#include <thread>
#include <algorithm>
#include <cmath>

namespace aad {

// Forward declarations
class Node;

// Thread-local tape storage
thread_local Tape* active_tape = nullptr;

// Node structure for the computation graph
struct Node {
    double value;
    double adjoint;
    std::vector<std::pair<Node*, double>> dependencies;  // (node, gradient contribution)
    std::vector<Node*> dependents;  // nodes that depend on this node

    Node(double v) : value(v), adjoint(0.0) {}

    // For operations that create new nodes
    Node(double v, std::vector<std::pair<Node*, double>> deps) 
        : value(v), adjoint(0.0), dependencies(std::move(deps)) {}
};

// Var class implementation
class Var {
private:
    Node* node;

    // Private constructor for internal use
    Var(Node* n) : node(n) {}

    friend class Tape;

public:
    Var(double value = 0.0) {
        // Create a new input node
        node = new Node(value);
        // Record this as an input node on the active tape
        Tape& tape = Tape::active();
        tape.recordInput(node);
    }

    double value() const {
        return node->value;
    }

    double adjoint() const {
        return node->adjoint;
    }

    Var& operator+=(const Var& other) {
        Tape& tape = Tape::active();
        node = tape.recordOp(2, node, other.node, [](double a, double b) { return a + b; }, 
                             [](double a, double b, double grad) { return grad; }, 
                             [](double a, double b, double grad) { return grad; });
        return *this;
    }

    Var& operator-=(const Var& other) {
        Tape& tape = Tape::active();
        node = tape.recordOp(2, node, other.node, [](double a, double b) { return a - b; }, 
                             [](double a, double b, double grad) { return grad; }, 
                             [](double a, double b, double grad) { return -grad; });
        return *this;
    }

    Var& operator*=(const Var& other) {
        Tape& tape = Tape::active();
        node = tape.recordOp(2, node, other.node, [](double a, double b) { return a * b; }, 
                             [](double a, double b, double grad) { return grad * b; }, 
                             [](double a, double b, double grad) { return grad * a; });
        return *this;
    }

    Var& operator/=(const Var& other) {
        Tape& tape = Tape::active();
        node = tape.recordOp(2, node, other.node, [](double a, double b) { return a / b; }, 
                             [](double a, double b, double grad) { return grad / b; }, 
                             [](double a, double b, double grad) { return -grad * a / (b * b); });
        return *this;
    }

    // Allow implicit conversion from double
    Var& operator=(double value) {
        node->value = value;
        return *this;
    }

    friend Var operator+(const Var& a, const Var& b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x + y; }, 
                                          [](double x, double y, double grad) { return grad; }, 
                                          [](double x, double y, double grad) { return grad; });
        return Var(result_node);
    }

    friend Var operator-(const Var& a, const Var& b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x - y; }, 
                                          [](double x, double y, double grad) { return grad; }, 
                                          [](double x, double y, double grad) { return -grad; });
        return Var(result_node);
    }

    friend Var operator*(const Var& a, const Var& b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x * y; }, 
                                          [](double x, double y, double grad) { return grad * y; }, 
                                          [](double x, double y, double grad) { return grad * x; });
        return Var(result_node);
    }

    friend Var operator/(const Var& a, const Var& b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x / y; }, 
                                          [](double x, double y, double grad) { return grad / y; }, 
                                          [](double x, double y, double grad) { return -grad * x / (y * y); });
        return Var(result_node);
    }

    friend Var operator-(const Var& a) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [](double x) { return -x; }, 
                                          [](double x, double grad) { return -grad; });
        return Var(result_node);
    }

    friend Var exp(const Var& a) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::exp(x); }, 
                                          [](double x, double grad) { return grad * std::exp(x); });
        return Var(result_node);
    }

    friend Var log(const Var& a) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::log(x); }, 
                                          [](double x, double grad) { return grad / x; });
        return Var(result_node);
    }

    friend Var sqrt(const Var& a) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::sqrt(x); }, 
                                          [](double x, double grad) { return grad / (2 * std::sqrt(x)); });
        return Var(result_node);
    }

    friend Var pow(const Var& a, double b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [b](double x) { return std::pow(x, b); }, 
                                          [b](double x, double grad) { return grad * b * std::pow(x, b - 1); });
        return Var(result_node);
    }

    friend Var normal_cdf(const Var& a) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(1, a.node, [](double x) { 
            // Standard normal CDF approximation using Abramowitz and Stegun
            const double a1 =  0.254829592;
            const double a2 = -0.284496736;
            const double a3 =  1.421413741;
            const double a4 = -1.453152027;
            const double a5 =  1.061405429;
            const double p  =  0.3275911;

            // Save the sign of x
            int sign = 1;
            if (x < 0)
                sign = -1;
            x = std::abs(x) / std::sqrt(2.0);

            // A&S formula 7.1.26
            double t = 1.0 / (1.0 + p * x);
            double y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * std::exp(-x * x);

            return 0.5 * (1.0 + sign * y);
        }, 
        [](double x, double grad) { 
            return grad * std::exp(-x * x / 2.0) / std::sqrt(2.0 * M_PI); 
        });
        return Var(result_node);
    }

    friend Var max(const Var& a, const Var& b) {
        Tape& tape = Tape::active();
        Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return std::max(x, y); }, 
                                          [](double x, double y, double grad) { 
                                              return x >= y ? grad : 0.0; 
                                          }, 
                                          [](double x, double y, double grad) { 
                                              return x >= y ? 0.0 : grad; 
                                          });
        return Var(result_node);
    }

    // Allow implicit conversion from double
    friend Var operator+(const Var& a, double b) {
        return a + Var(b);
    }

    friend Var operator+(double a, const Var& b) {
        return Var(a) + b;
    }

    friend Var operator-(const Var& a, double b) {
        return a - Var(b);
    }

    friend Var operator-(double a, const Var& b) {
        return Var(a) - b;
    }

    friend Var operator*(const Var& a, double b) {
        return a * Var(b);
    }

    friend Var operator*(double a, const Var& b) {
        return Var(a) * b;
    }

    friend Var operator/(const Var& a, double b) {
        return a / Var(b);
    }

    friend Var operator/(double a, const Var& b) {
        return Var(a) / b;
    }
};

// Tape implementation
class Tape {
private:
    std::vector<Node*> nodes;
    std::vector<std::size_t> input_indices;
    std::size_t current_pos;
    std::size_t reserved_size;

public:
    struct Mark { std::size_t pos; };

    static Tape& active() {
        if (active_tape == nullptr) {
            active_tape = new Tape();
        }
        return *active_tape;
    }

    std::size_t size() const {
        return nodes.size();
    }

    void reserve(std::size_t nodes) {
        reserved_size = nodes;
        if (nodes > 0) {
            nodes.reserve(nodes);
        }
    }

    Mark mark() const {
        return {current_pos};
    }

    void rewind(Mark m) {
        // Clear nodes from m.pos onwards
        for (std::size_t i = m.pos; i < nodes.size(); ++i) {
            delete nodes[i];
        }
        nodes.resize(m.pos);
        current_pos = m.pos;
    }

    void clear() {
        for (Node* node : nodes) {
            delete node;
        }
        nodes.clear();
        input_indices.clear();
        current_pos = 0;
    }

    void reset_adjoints() {
        for (Node* node : nodes) {
            node->adjoint = 0.0;
        }
    }

    void propagate(const Var& output) {
        // Reset all adjoints to 0
        reset_adjoints();

        // Set the output adjoint to 1.0 (seed)
        output.node->adjoint = 1.0;

        // Backward pass: compute adjoints for all nodes
        // We'll do this in reverse topological order
        std::vector<Node*> reverse_nodes(nodes.rbegin(), nodes.rend());

        for (Node* node : reverse_nodes) {
            // Propagate adjoint to dependencies
            for (const auto& dep : node->dependencies) {
                Node* dep_node = dep.first;
                double grad_contribution = dep.second;
                dep_node->adjoint += node->adjoint * grad_contribution;
            }
        }
    }

    // Internal method to record input nodes
    void recordInput(Node* node) {
        input_indices.push_back(nodes.size());
        nodes.push_back(node);
        current_pos = nodes.size();
    }

    // Internal method to record operations
    template<typename Op, typename Grad1, typename Grad2>
    Node* recordOp(std::size_t n_args, Node* arg1, Node* arg2, Op op, Grad1 grad1, Grad2 grad2) {
        // Create new node for the result
        double result_value = op(arg1->value, arg2->value);
        Node* result_node = new Node(result_value);

        // Add dependencies
        result_node->dependencies.push_back({arg1, grad1(arg1->value, arg2->value, 1.0)});
        result_node->dependencies.push_back({arg2, grad2(arg1->value, arg2->value, 1.0)});

        // Add to nodes list
        nodes.push_back(result_node);
        current_pos = nodes.size();

        return result_node;
    }

    // Internal method to record unary operations
    template<typename Op, typename Grad>
    Node* recordOp(std::size_t n_args, Node* arg, Op op, Grad grad) {
        // Create new node for the result
        double result_value = op(arg->value);
        Node* result_node = new Node(result_value);

        // Add dependency
        result_node->dependencies.push_back({arg, grad(arg->value, 1.0)});

        // Add to nodes list
        nodes.push_back(result_node);
        current_pos = nodes.size();

        return result_node;
    }
};

// Implement the static methods
Tape& Tape::active() {
    if (active_tape == nullptr) {
        active_tape = new Tape();
    }
    return *active_tape;
}

std::size_t Tape::size() const {
    return nodes.size();
}

void Tape::reserve(std::size_t nodes) {
    reserved_size = nodes;
    if (nodes > 0) {
        this->nodes.reserve(nodes);
    }
}

Tape::Mark Tape::mark() const {
    return {current_pos};
}

void Tape::rewind(Mark m) {
    // Clear nodes from m.pos onwards
    for (std::size_t i = m.pos; i < nodes.size(); ++i) {
        delete nodes[i];
    }
    nodes.resize(m.pos);
    current_pos = m.pos;
}

void Tape::clear() {
    for (Node* node : nodes) {
        delete node;
    }
    nodes.clear();
    input_indices.clear();
    current_pos = 0;
}

void Tape::reset_adjoints() {
    for (Node* node : nodes) {
        node->adjoint = 0.0;
    }
}

void Tape::propagate(const Var& output) {
    // Reset all adjoints to 0
    reset_adjoints();

    // Set the output adjoint to 1.0 (seed)
    output.node->adjoint = 1.0;

    // Backward pass: compute adjoints for all nodes
    // We'll do this in reverse topological order
    std::vector<Node*> reverse_nodes(nodes.rbegin(), nodes.rend());

    for (Node* node : reverse_nodes) {
        // Propagate adjoint to dependencies
        for (const auto& dep : node->dependencies) {
            Node* dep_node = dep.first;
            double grad_contribution = dep.second;
            dep_node->adjoint += node->adjoint * grad_contribution;
        }
    }
}

// Var methods
Var::Var(double value) {
    // Create a new input node
    node = new Node(value);
    // Record this as an input node on the active tape
    Tape& tape = Tape::active();
    tape.recordInput(node);
}

double Var::value() const {
    return node->value;
}

double Var::adjoint() const {
    return node->adjoint;
}

Var& Var::operator+=(const Var& other) {
    Tape& tape = Tape::active();
    node = tape.recordOp(2, node, other.node, [](double a, double b) { return a + b; }, 
                         [](double a, double b, double grad) { return grad; }, 
                         [](double a, double b, double grad) { return grad; });
    return *this;
}

Var& Var::operator-=(const Var& other) {
    Tape& tape = Tape::active();
    node = tape.recordOp(2, node, other.node, [](double a, double b) { return a - b; }, 
                         [](double a, double b, double grad) { return grad; }, 
                         [](double a, double b, double grad) { return -grad; });
    return *this;
}

Var& Var::operator*=(const Var& other) {
    Tape& tape = Tape::active();
    node = tape.recordOp(2, node, other.node, [](double a, double b) { return a * b; }, 
                         [](double a, double b, double grad) { return grad * b; }, 
                         [](double a, double b, double grad) { return grad * a; });
    return *this;
}

Var& Var::operator/=(const Var& other) {
    Tape& tape = Tape::active();
    node = tape.recordOp(2, node, other.node, [](double a, double b) { return a / b; }, 
                         [](double a, double b, double grad) { return grad / b; }, 
                         [](double a, double b, double grad) { return -grad * a / (b * b); });
    return *this;
}

Var operator+(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x + y; }, 
                                      [](double x, double y, double grad) { return grad; }, 
                                      [](double x, double y, double grad) { return grad; });
    return Var(result_node);
}

Var operator-(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x - y; }, 
                                      [](double x, double y, double grad) { return grad; }, 
                                      [](double x, double y, double grad) { return -grad; });
    return Var(result_node);
}

Var operator*(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x * y; }, 
                                      [](double x, double y, double grad) { return grad * y; }, 
                                      [](double x, double y, double grad) { return grad * x; });
    return Var(result_node);
}

Var operator/(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x / y; }, 
                                      [](double x, double y, double grad) { return grad / y; }, 
                                      [](double x, double y, double grad) { return -grad * x / (y * y); });
    return Var(result_node);
}

Var operator-(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return -x; }, 
                                      [](double x, double grad) { return -grad; });
    return Var(result_node);
}

Var exp(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::exp(x); }, 
                                      [](double x, double grad) { return grad * std::exp(x); });
    return Var(result_node);
}

Var log(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::log(x); }, 
                                      [](double x, double grad) { return grad / x; });
    return Var(result_node);
}

Var sqrt(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::sqrt(x); }, 
                                      [](double x, double grad) { return grad / (2 * std::sqrt(x)); });
    return Var(result_node);
}

Var pow(const Var& a, double b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [b](double x) { return std::pow(x, b); }, 
                                      [b](double x, double grad) { return grad * b * std::pow(x, b - 1); });
    return Var(result_node);
}

Var normal_cdf(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { 
        // Standard normal CDF approximation using Abramowitz and Stegun
        const double a1 =  0.254829592;
        const double a2 = -0.284496736;
        const double a3 =  1.421413741;
        const double a4 = -1.453152027;
        const double a5 =  1.061405429;
        const double p  =  0.3275911;

        // Save the sign of x
        int sign = 1;
        if (x < 0)
            sign = -1;
        x = std::abs(x) / std::sqrt(2.0);

        // A&S formula 7.1.26
        double t = 1.0 / (1.0 + p * x);
        double y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * std::exp(-x * x);

        return 0.5 * (1.0 + sign * y);
    }, 
    [](double x, double grad) { 
        return grad * std::exp(-x * x / 2.0) / std::sqrt(2.0 * M_PI); 
    });
    return Var(result_node);
}

Var max(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return std::max(x, y); }, 
                                      [](double x, double y, double grad) { 
                                          return x >= y ? grad : 0.0; 
                                      }, 
                                      [](double x, double y, double grad) { 
