            delete nodes[i];
        }
        nodes.resize(m.pos);
        current_pos = m.pos;
    }

    void clear() {
        for (Node* node : nodes) {
            delete node;
        }
        nodes.clear();
        input_indices.clear();
        current_pos = 0;
    }

