namespace aad {
class Var;

// Node structure for the computation graph
struct Node {
    double value;
    double adjoint;
    std::vector<std::pair<Node*, double>> dependencies;  // (node, gradient contribution)

    Node(double v) : value(v), adjoint(0.0) {}
};

// One tape per thread: Tape::active() returns this thread's tape.
class Tape {
private:
    std::vector<Node*> nodes;
    std::vector<std::size_t> input_indices;
    std::size_t current_pos;
    std::size_t reserved_size;

public:
    struct Mark { std::size_t pos; };
    static Tape& active();
    std::size_t size() const;          // number of recorded nodes
    void reserve(std::size_t nodes);   // after reserve(n), recording up to n nodes allocates nothing
    Mark mark() const;
    void rewind(Mark m);               // drops the nodes recorded after m
    void clear();                      // empties the tape
    void reset_adjoints();             // sets every adjoint to 0
    void propagate(const Var& output); // resets adjoints, seeds output with 1, sweeps back

    // Internal method to record input nodes
    void recordInput(Node* node);

    // Internal method to record operations
    template<typename Op, typename Grad1, typename Grad2>
    Node* recordOp(std::size_t n_args, Node* arg1, Node* arg2, Op op, Grad1 grad1, Grad2 grad2);

    // Internal method to record unary operations
    template<typename Op, typename Grad>
    Node* recordOp(std::size_t n_args, Node* arg, Op op, Grad grad);
};

class Var {
private:
    Node* node;

    // Private constructor for internal use
    Var(Node* n) : node(n) {}

    friend class Tape;

public:
    Var(double value = 0.0);           // records a new input node
    double value() const;
    double adjoint() const;            // d(output)/d(this) after Tape::propagate
    Var& operator+=(const Var&);
