    return node->adjoint;
}

// Tape methods
Tape& Tape::active() {
    thread_local static Tape tape;
    return tape;
}

std::size_t Tape::size() const {
    return nodes.size();
}

void Tape::reserve(std::size_t n) {
    reserved_size = n;
    nodes.reserve(n);
}

Tape::Mark Tape::mark() const {
    return Mark{current_pos};
}

void Tape::rewind(Mark m) {
    // Clear nodes after the mark
    for (std::size_t i = m.pos; i < nodes.size(); ++i) {
        delete nodes[i];
    }
    nodes.resize(m.pos);
    current_pos = m.pos;
}

void Tape::clear() {
    for (auto node : nodes) {
        delete node;
    }
    nodes.clear();
    input_indices.clear();
    current_pos = 0;
}

