    Var(double value = 0.0);           // records a new input node
    double value() const;
    double adjoint() const;            // d(output)/d(this) after Tape::propagate
    Var& operator+=(const Var&);
    Var& operator-=(const Var&);
    Var& operator*=(const Var&);
    Var& operator/=(const Var&);
    // private representation is up to you
};

// Binary operators
inline Var operator+(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x + y; }, 
                                      [](double x, double y, double grad) { return grad; }, 
                                      [](double x, double y, double grad) { return grad; });
    return Var(result_node);
}

inline Var operator-(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x - y; }, 
                                      [](double x, double y, double grad) { return grad; }, 
                                      [](double x, double y, double grad) { return -grad; });
    return Var(result_node);
}

inline Var operator*(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x * y; }, 
                                      [](double x, double y, double grad) { return grad * y; }, 
                                      [](double x, double y, double grad) { return grad * x; });
    return Var(result_node);
}

inline Var operator/(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return x / y; }, 
                                      [](double x, double y, double grad) { return grad / y; }, 
                                      [](double x, double y, double grad) { return -grad * x / (y * y); });
    return Var(result_node);
}

inline Var operator-(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return -x; }, 
                                      [](double x, double grad) { return -grad; });
    return Var(result_node);
}

// Scalar operators
inline Var operator*(double a, const Var& b) {
    return Var(a) * b;
}

inline Var operator/(const Var& a, double b) {
    return a / Var(b);
}

inline Var operator/(double a, const Var& b) {
    return Var(a) / b;
}

// Mathematical functions
inline Var exp(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::exp(x); }, 
                                      [](double x, double grad) { return grad * std::exp(x); });
    return Var(result_node);
}

inline Var log(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::log(x); }, 
                                      [](double x, double grad) { return grad / x; });
    return Var(result_node);
}

inline Var sqrt(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) { return std::sqrt(x); }, 
                                      [](double x, double grad) { return grad / (2.0 * std::sqrt(x)); });
    return Var(result_node);
}

inline Var pow(const Var& a, double b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [b](double x) { return std::pow(x, b); },
                                      [b](double x, double grad) { return grad * b * std::pow(x, b - 1.0); });
    return Var(result_node);
}

inline Var normal_cdf(const Var& a) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(1, a.node, [](double x) {
        return 0.5 * (1.0 + std::erf(x / std::sqrt(2.0)));
    }, [](double x, double grad) {
        return grad * std::exp(-x * x / 2.0) / std::sqrt(2.0 * M_PI);
    });
    return Var(result_node);
}

inline Var max(const Var& a, const Var& b) {
    Tape& tape = Tape::active();
    Node* result_node = tape.recordOp(2, a.node, b.node, [](double x, double y) { return std::max(x, y); },
                                      [](double x, double y, double grad) {
                                          return x >= y ? grad : 0.0;
                                      },
                                      [](double x, double y, double grad) {
                                          return x >= y ? 0.0 : grad;
                                      });
    return Var(result_node);
}

// Template implementations
template<typename Op, typename Grad1, typename Grad2>
Node* Tape::recordOp(std::size_t n_args, Node* arg1, Node* arg2, Op op, Grad1 grad1, Grad2 grad2) {
    // Create new node for the result
    double result_value = op(arg1->value, arg2->value);
    Node* result_node = new Node(result_value);

    // Add dependencies
    result_node->dependencies.push_back({arg1, grad1(arg1->value, arg2->value, 1.0)});
    result_node->dependencies.push_back({arg2, grad2(arg1->value, arg2->value, 1.0)});

    // Add to nodes list
    nodes.push_back(result_node);
    current_pos = nodes.size();

    return result_node;
}

template<typename Op, typename Grad>
Node* Tape::recordOp(std::size_t n_args, Node* arg, Op op, Grad grad) {
    // Create new node for the result
    double result_value = op(arg->value);
    Node* result_node = new Node(result_value);

    // Add dependency
    result_node->dependencies.push_back({arg, grad(arg->value, 1.0)});

    // Add to nodes list
    nodes.push_back(result_node);
    current_pos = nodes.size();

    return result_node;
}

}  // namespace aad

